UPDATE XXLGE_RESP_USER_MASTER
   SET attribute1          = #{mailSendFlag}
     , last_update_date    = SYSDATE
     , last_updated_by     = #{USER_SESSION.applicationUserId}
 WHERE responsibility_id   = #{responsibilityId}
   AND responsibility_key  = #{responsibilityKey}
   AND responsibility_name = #{responsibilityName}
   AND section             = #{section}
